const isEven = (value) => value % 2 === 0;

function sumEven(values) {
  let total = 0;
  for (const value of values) {
    if (isEven(value)) total += value;
  }
  return total;
}

console.log(sumEven([2, 3, 8]));

const rows = [
  { category: "study", minutes: 30 },
