const loadScore = async (id) => {
  if (id < 0) throw new RangeError("Invalid ID");
  return id * 2;
};

async function main() {
  try {
    const scores = await Promise.all([loadScore(2), loadScore(4)]);
    console.log(scores);
  } catch (error) {
    console.error(error.message);
  }
}
main();

import { writeFile, readFile, mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

const folder = await mkdtemp(join(tmpdir(), "ion-js-"));
try {
  const file = join(folder, "score.json");
  await writeFile(file, JSON.stringify({ score: 9 }), "utf8");
  console.log(JSON.parse(await readFile(file, "utf8")).score);
} finally {
  await rm(folder, { recursive: true, force: true });
}
